hooks.command:
node -e "
const fs = require('fs');
let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  try {
    const data = JSON.parse(input);
    const fp = data.tool_input?.file_path || data.tool_input?.new_file_path;
    if (!fp || !fp.match(/\.(js|jsx|ts|tsx)$/)) process.exit(0);
    if (!fs.existsSync(fp)) process.exit(0);
    const lines = fs.readFileSync(fp, 'utf8').split('\n').length;
    const budgets = { controller: 100, hook: 150, service: 200, component: 200, model: 250 };
    let type = 'component';
    if (fp.includes('controller')) type = 'controller';
    else if (fp.includes('/hooks/') || fp.match(/use[A-Z]/)) type = 'hook';
    else if (fp.includes('service')) type = 'service';
    else if (fp.includes('model')) type = 'model';
    const budget = budgets[type];
    if (lines > budget) {
      process.stderr.write('FILE BUDGET EXCEEDED: ' + fp.split('/').pop() + ' = ' + lines + 'L (budget: ' + budget + 'L for ' + type + '). Split before committing.\n');
      process.exit(0);
    }
  } catch(e) { process.exit(0); }
});
"
